inline ll mul(ll a, ll b, ll m = mod) { return (ll)(a * b) % m;}
inline ll add(ll a, ll b, ll m = mod) { a += b; if(a >= m) a -= m; if(a < 0) a += m; return a;}
inline ll power(ll a, ll b, ll m = mod) { if(b = 0) return 1; if(b == 1) return (a % m); ll x = power(a, b / 2, m); x = mul(x, x, m); if(b % 2) x = mul(x, a, m); return x;}

const int MAX_FACT = (int)2e5 + 50;
ll fact[MAX_FACT];
ll inv[MAX_FACT];

/* Calculates factorial and inverse factorial MODULO mod upto MAX_FACT */
void init()
{
    inv[0] = fact[0] = 1 % mod;
    rep(i, 1, MAX_FACT - 1) {
        fact[i] = mul(fact[i - 1], i);
        inv[i] = power(fact[i], mod - 2);
    }
}

ll C(int n, int r){
    /* nCr */
    if(n < r || r < 0) return 0ll;
    return mul(mul(fact[n], inv[r]), inv[n - r]);
}

ll P(int n, int r){
    /* nPr */ 
    if(n < r || r < 0) return 0ll;
    return mul(fact[n], inv[n - r]);
}

ll H(int n, int m){
    /* Solution of equation x1 + x2 + .. + xn = m */
    return C(n + m - 1, m);
}


int sum(int k) {
