int main()
{
	int n, j, k, sum;
	scanf("%d", &n);
	int arr[n];
	for(int i=0; i<n; i++)
		scanf("%d", arr+i);
	for(j=0, k=n-1; ; )
	{
		if(arr[j] = arr[k])
		{
			sum=0;
			j++;
			k--;
		}
		else if(arr[j]<arr[k])
		{
			arr[k]=arr[k]-arr[j];
			sum=arr[k];
			j++;
		}
		else
		{
			arr[j]=arr[j]-arr[k];
			sum=arr[j];
			k--;
		}
		if(j>=k)
			break;
	}
	printf("%d\n", sum);
	return 0;
}

