inline ll read(){
    ll s = 0, w = 1; char ch = getchar();
    while(ch < '0' || ch > '9'){ if(ch == '-') w = -1; ch = getchar();}
    while(ch >= '0' && ch <= '9') s = s * 10 + ch - '0', ch = getchar();
    return s * w;
}

inline void print(ll x){
    if(x < 0) x = ~x + 1, putchar('-');
    if(x >= 9) print(x / 10);
    putchar(x % 10 + '0');
}

int main(){
    n = read(); k = read();
    for(ll i = 0; i < k; i++) x += i;
    for(ll i = n; i > n - k; i--) y += i;
    ans = (ans + y - x + 1) % mod;
    for(ll i = k + 1; i <= n + 1; i++){
        x += i - 1; y += n - i + 1;
        ans = (ans + y - x + 1) % mod;
    }
    print(ans);

    return 0;
}

