			vect[i] = vect[i - 1] + temp;
		}
	}
	int t1 = vect[n - 1] - vect[0] - vect[0];
	if (t1 < 0)
	{
		t1 = t1 * -1;
	}
	int t2 = 0;
	for (int i = 1; i < n-1; i++)
	{
		t2 = vect[n - 1] - vect[i] - vect[i];
		if (t2 < 0)
		{
			t2 = t2 * -1;
		}
		if (t2 < t1)
		{
			t1 = t2;
		}
	}
	cout << t1 << endl;
	return 0;
}

